// pes_dispatch.hpp: runtime dispatch for translated indirect calls. The table
// maps PES code VAs to translated functions. pes_dispatch_gen.hpp (committed,
// generated by tools/dev/translate/gen_translated.py) is the table itself. A
// target missing from the table fails loudly (PES_DISPATCH_UNTRANSLATED), never
// silently.
#pragma once
#include <cstdint>

struct PesState;

struct PesDispatch {
  void (*fn)(PesState&);
};

PesDispatch pes_dispatch_lookup(uint64_t t);
[[noreturn]] void pes_dispatch_missing(uint64_t t);

// The table itself, committed beside this header.
#include "pes_dispatch_gen.hpp"
